The code for the binary min-heap data structure in C is given below:

```
#include <stdio.h>
#include <stdlib.h>

#define DEFAULT_CAPACITY 10

typedef struct Heap {
    int size;
    int capacity;
    int *data;
} Heap;

// function prototypes
Heap* create_heap(int capacity);
void destroy_heap(Heap* heap);
void insert(Heap* heap, int value);
int extract_min(Heap* heap);
int peek(Heap* heap);
int size(Heap* heap);
int is_empty(Heap* heap);
void percolate_up(Heap* heap, int index);
void percolate_down(Heap* heap, int index);

// create a new binary min-heap with the given capacity
Heap* create_heap(int capacity) {
    Heap* heap = malloc(sizeof(Heap));
    heap->size = 0;
    heap->capacity = capacity < DEFAULT_CAPACITY ? DEFAULT_CAPACITY : capacity;
    heap->data = calloc(heap->capacity, sizeof(int));
    return heap;
}

// free the memory allocated for the binary min-heap
void destroy_heap(Heap* heap) {
    free(heap->data);
    free(heap);
}

// add a new element to the binary min-heap and maintain the heap property
void insert(Heap* heap, int value) {
    if (heap->size == heap->capacity) {
        // double the capacity of the heap if it is full
        heap->capacity *= 2;
        heap->data = realloc(heap->data, heap->capacity * sizeof(int));
    }
    heap->data[heap->size] = value;
    percolate_up(heap, heap->size);
    heap->size++;
}

// remove and return the minimum element from the binary min-heap and maintain the heap property
int extract_min(Heap* heap) {
    if (heap->size == 0) {
        printf("Heap is empty\n");
        return -1;
    }
    int min = heap->data[0];
    heap->data[0] = heap->data[heap->size - 1];
    heap->size--;
    percolate_down(heap, 0);
    return min;
}

// return the minimum element in the binary min-heap without removing it
int peek(Heap* heap) {
    if (heap->size == 0) {
        printf("Heap is empty\n");
        return -1;
    }
    return heap->data[0];
}

// return the number of elements in the binary min-heap
int size(Heap* heap) {
    return heap->size;
}

// return true if the binary min-heap is empty, false otherwise
int is_empty(Heap* heap) {
    return heap->size == 0;
}

// maintain the heap property by percolating up the element at the given index
void percolate_up(Heap* heap, int index) {
    int parent = (index - 1) / 2;
    if (index > 0 && heap->data[index] < heap->data[parent]) {
        int temp = heap->data[index];
        heap->data[index] = heap->data[parent];
        heap->data[parent] = temp;
        percolate_up(heap, parent);
    }
}

// maintain the heap property by percolating down the element at the given index
void percolate_down(Heap* heap, int index) {
    int left = 2 * index + 1;
    int right = 2 * index + 2;
    int min = index;
    if (left < heap->size && heap->data[left] < heap->data[min]) {
        min = left;
    }
    if (right < heap->size && heap->data[right] < heap->data[min]) {
        min = right;
    }
    if (min != index) {
        int temp = heap->data[index];
        heap->data[index] = heap->data[min];
        heap->data[min] = temp;
        percolate_down(heap, min);
    }
}
```

