// function to check if a given string is palindrome or not
bool isPalindrome(string str)
{
    int len = str.length();

    // loop through the string and compare characters from both ends
    for (int I = 0; I < len / 2; i++) {
        if (str[i] != str[len - I - 1])
            return false;
    }

    return true;
}

// function to find the longest palindrome within a given string
string findLongestPalindrome(string str)
{
    int maxLen = 0;
    string longestPalindrome = "";

    // loop through the string and consider each substring
    for (int I = 0; I < str.length(); i++) {
        for (int j = i; j < str.length(); j++) {

            // check if the substring is alphanumeric and ignore case
            if (isalnum(str[i]) && isalnum(str[j]) && tolower(str[i]) == tolower(str[j])) {

                // create a substring and check if it's a palindrome
                string subStr = str.substr(i, j - I + 1);
                if (isPalindrome(subStr)) {

                    // check if the length of the palindrome is greater than the current max length
                    if (subStr.length() > maxLen) {
                        maxLen = subStr.length();
                        longestPalindrome = subStr;
                    }
                }
            }
        }
    }

    return longestPalindrome;
}

int main()
{
    string str = "A man, a plan, a canal, Panama!";
    string longestPalindrome = findLongestPalindrome(str);

    cout << "Longest palindrome: " << longestPalindrome << endl;

    return 0;
}
```

