One possible implementation of a priority queue data structure in C# using a binary heap is as follows:

```csharp
public class PriorityQueue<T>
{
    private List<(T, int)> heap; // binary heap represented as a list of (value, priority) pairs

    public PriorityQueue()
    {
        heap = new List<(T, int)>();
    }

    public void Insert(T value, int priority)
    {
        heap.Add((value, priority)); // add to end of heap
        int I = heap.Count - 1;
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (heap[parent].Item2 >= priority) break; // already in correct place
            heap[i] = heap[parent]; // swap with parent
            I = parent;
        }
        heap[i] = (value, priority); // insert at correct place
    }

    public T DeleteHighestPriority()
    {
        if (heap.Count == 0) throw new InvalidOperationException("Priority queue is empty");
        T result = heap[0].Item1; // highest-priority value
        int last = heap.Count - 1;
        int I = 0;
        while (true)
        {
            int left = 2 * I + 1;
            int right = 2 * I + 2;
            if (left > last) break; // no children
            int j = left;
            if (right <= last && heap[right].Item2 > heap[left].Item2)
            {
                j = right; // choose larger child
            }
            if (heap[j].Item2 <= heap[last].Item2) break; // already in correct place
            heap[i] = heap[j]; // swap with larger child
            I = j;
        }
        heap[i] = heap[last]; // move last element to correct place
        heap.RemoveAt(last); // remove last element
        return result;
    }

    public T PeekHighestPriority()
    {
        if (heap.Count == 0) throw new InvalidOperationException("Priority queue is empty");
        return heap[0].Item1; // highest-priority value
    }

    public bool IsEmpty()
    {
        return heap.Count == 0;
    }
}
```

This implementation uses a binary heap to maintain the elements in the priority queue. Each element is represented as a `(value, priority)` pair. The `Insert` method adds a new element to the end of the heap and then moves it upwards to its correct position by comparing it with its parent and swapping if necessary. The `DeleteHighestPriority` method removes the root element (which has the highest priority) and then moves the last element to the root position, swapping with its larger child if necessary to maintain the heap property. The `PeekHighestPriority` method returns the value of the root element without removing it. The `IsEmpty` method checks if the heap is empty.

