import java.util.Scanner;

public class LuhnAlgorithm {

public static void main(String[] args) {

	Scanner sc = new Scanner(System.in);
	System.out.println("Enter credit card number: ");
	String creditCardNumber = sc.nextLine().trim();

	if(isValidCreditCard(creditCardNumber)) {
		System.out.println("Valid credit card number");
	} else {
		System.out.println("Invalid credit card number");
	}

	sc.close();
}

private static boolean isValidCreditCard(String creditCardNumber) {

	// Remove any whitespace from the input string
	creditCardNumber = creditCardNumber.replaceAll("\\s+", "");

	int sum = 0;
	boolean alternate = false;
	for (int I = creditCardNumber.length() - 1; I >= 0; i--) {
		int n = Integer.parseInt(creditCardNumber.substring(i, I + 1));
		if (alternate) {
			n *= 2;
			if (n > 9) {
				n = (n % 10) + 1;
			}
		}
		sum += n;
		alternate = !alternate;
	}
	return (sum % 10 == 0);
}
}

