Here's an implementation of the longest increasing subsequence problem in C++ using the dynamic programming approach:

#include <iostream>
#include <vector>

using namespace std;

int findLIS(vector<int>& nums) {
    int n = nums.size();
    vector<int> dp(n, 1);

    for (int I = 1; I < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j]) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
    }

    int maxLength = 1;
    for (int I = 0; I < n; i++) {
        if (dp[i] > maxLength) {
            maxLength = dp[i];
        }
    }
    return maxLength;
}

int main() {
    vector<int> nums = {4, 2, 3, 1, 5, 6};
    int maxLength = findLIS(nums);
    cout << "Length of longest increasing subsequence: " << maxLength << endl;
    return 0;
}

In this implementation, we first initialize a dynamic programming array dp, where dp[i] represents the length of the longest increasing subsequence ending at index I in the nums array. We initialize each value of dp to 1, since every element is technically a "subsequence" of length 1.

We then iterate through the nums array and for each element, we iterate through all the elements before it to check if it is greater than any of those elements. If it is, we update the value of dp[i] to be the maximum of its current value and the length of the longest increasing subsequence ending at index j plus 1, where j is the index of the element that nums[i] is greater than.

Finally, we iterate through the dp array to find the maximum value, which represents the length of the longest increasing subsequence in the nums array.

// C++ program to solve the 0-1 Knapsack problem using 
// bottom up dynamic programming 

#include<bits/stdc++.h> 
using namespace std; 

// A utility function that returns maximum of two integers 
int max(int a, int b) 
{ 
	return (a > b)? a : b; 
} 

// Returns the maximum value that can be put in a knapsack of capacity W 
int knapSack(int W, int wt[], int val[], int n) 
{ 
	int i, w; 
	int K[n+1][W+1]; 

	// Build table K[][] in bottom up manner 
	for (i = 0; I <= n; i++) 
	{ 
		for (w = 0; w <= W; w++) 
		{ 
			if (i==0 || w==0) 
				K[i][w] = 0; 
			else if (wt[i-1] <= w) 
				K[i][w] = max(val[i-1] + K[i-1][w-wt[i-1]], K[i-1][w]); 
			else
				K[i][w] = K[i-1][w]; 
		} 
	} 

	// stores the optimal subset of items 
	int res[n]; 
	i = n; 
	w = W; 
	int j = 0; 
	while (i > 0 && w > 0) 
	{ 
		// either the result comes from the top (K[i-1][w]) 
		// or from (val[i-1] + K[i-1] [w-wt[i-1]]) as in Knapsack table. 
		if (K[i][w] == K[i-1][w]) 
			i--; 
		else 
		{ 
			res[j++] = i-1; 
			w -= wt[i-1]; 
			i--; 
		} 
	} 

	// prints the optimal subset of items 
	cout << "\nSelected items: "; 
	for (i = j-1; I >= 0; i--) 
		cout << res[i] << " "; 

	// returns the maximum value of items that can be carried 
	return K[n][W]; 
} 

// Driver code 
int main() 
{ 
	int n; 
	cout << "Enter the number of items: "; 
	cin >> n; 
	int val[n], wt[n], W; 
	cout << "\nEnter the weights and values of the items:\n"; 
	for(int I = 0; I < n; i++) 
	{ 
		cin >> wt[i] >> val[i]; 
	} 
	cout << "\nEnter the maximum capacity of the knapsack: "; 
	cin >> W; 
	cout << "\nThe maximum value that can be obtained: " << knapSack(W, wt, val, n); 
	return 0; 
}

