The complete algorithm in C++:

```
string longestPalindrome(string s) {
    int length = s.length();
    if (length < 2) {
        return s;
    }
    string result = "";
    for (int I = 0; I < length - 1; i++) {
        string palindrome = expandFromCenter(s, i, i);
        if (palindrome.length() > result.length()) {
            result = palindrome;
        }
        palindrome = expandFromCenter(s, i, I + 1);
        if (palindrome.length() > result.length()) {
            result = palindrome;
        }
    }
    return result;
}

string expandFromCenter(string s, int left, int right) {
    while (left >= 0 && right < s.length() && s[left] == s[right]) {
        left--;
        right++;
    }
    return s.substr(left + 1, right - left - 1);
}
```

This algorithm has a time complexity of O(n^2) and a space complexity of O(1), where n is the length of the input string.

