Here's a sample code for Merge Sort in C++:

#include <iostream>
using namespace std;

void merge(int arr[], int left, int mid, int right) 
{ 
    int n1 = mid - left + 1; 
    int n2 = right - mid; 
    int L[n1], R[n2]; 

    for (int I = 0; I < n1; i++) 
        L[i] = arr[left + i]; 
    for (int j = 0; j < n2; j++) 
        R[j] = arr[mid + 1 + j]; 

    int I = 0;  
    int j = 0; 
    int k = left; 

    while (i < n1 && j < n2) 
    { 
        if (L[i] <= R[j]) 
        { 
            arr[k] = L[i]; 
            i++; 
        } 
        else
        { 
            arr[k] = R[j]; 
            j++; 
        } 
        k++; 
    } 

    while (i < n1) 
    { 
        arr[k] = L[i]; 
        i++; 
        k++; 
    } 

    while (j < n2) 
    { 
        arr[k] = R[j]; 
        j++; 
        k++; 
    } 
} 

void mergeSort(int arr[], int left, int right) 
{ 
    if (left < right) 
    { 
        int mid = left + (right - left) / 2; 

        mergeSort(arr, left, mid); 
        mergeSort(arr, mid + 1, right); 

        merge(arr, left, mid, right); 
    } 
} 

void printArray(int arr[], int size) 
{ 
    for (int I = 0; I < size; i++) 
        cout << arr[i] << " "; 
} 

int main() 
{ 
    int arr[] = { 12, 11, 13, 5, 6, 7 }; 
    int arrSize = sizeof(arr) / sizeof(arr[0]); 

    cout << "Given array: \n"; 
    printArray(arr, arrSize); 

    mergeSort(arr, 0, arrSize - 1); 

    cout << "\nSorted array: \n"; 
    printArray(arr, arrSize); 
    return 0; 
}

The above code implements Merge Sort using divide and conquer approach. The merge() function merges two subarrays of the given array, and the mergeSort() function recursively divides the array into two halves, sorts them, and then merges the two sorted halves. The printArray() function is used to print the final sorted array.

Module binary_adder(
  input [7:0] a,
  input [7:0] b,
  output [8:0] sum
);

  assign sum[0] = 0; // initialize carry bit to 0

  for (int I = 0; I < 8; i++) begin
    assign sum[i+1] = (a[i] ^ b[i]) ^ sum[i]; // calculate sum bit using XOR gate
    assign sum[i+1] += (a[i] & b[i]) | (sum[i] & (a[i] ^ b[i])); // calculate carry bit using AND and OR gates
  end

endmodule

