#include <string>
using namespace std;

string CaesarCipher(string message, int key, bool encrypt);

int main()
{
    string message;
    int key;
    char operation;

    // Get input from user
    cout << "Enter message: ";
    getline(cin, message);

    cout << "Enter key: ";
    cin >> key;

    cout << "Do you want to encrypt (e) or decrypt (d) the message? ";
    cin >> operation;

    // Perform encryption or decryption
    if (operation == 'e' || operation == 'E')
    {
        message = CaesarCipher(message, key, true);
        cout << "Encrypted message: " << message << endl;
    }
    else if (operation == 'd' || operation == 'D')
    {
        message = CaesarCipher(message, key, false);
        cout << "Decrypted message: " << message << endl;
    }
    else
    {
        cout << "Invalid operation" << endl;
    }

    return 0;
}

string CaesarCipher(string message, int key, bool encrypt)
{
    string result = "";

    // Shift each letter in the message according to the key value
    for (int I = 0; I < message.length(); i++)
    {
        char c = message[i];

        if (isalpha(c))
        {
            // Determine whether to shift uppercase or lowercase letters
            char base = isupper(c) ? 'A' : 'a';

            // Shift the letter and wrap around if necessary
            char shifted = base + (((c - base) + key * (encrypt ? 1 : -1)) % 26 + 26) % 26;

            result += shifted;
        }
        else
        {
            result += c;
        }
    }

    return result;
}

