Here is a Kotlin program that reads an array of integers from the user input and finds the minimum and maximum values in it. The program then prints the values along with their positions in the array.

```kotlin
import java.util.*

fun main(args: Array<String>) {

    // Read the array from user input
    val scanner = Scanner(System.`in`)
    print("Enter the size of the array: ")
    val size = scanner.nextInt()
    val array = IntArray(size)

    println("Enter the elements of the array:")
    for (i in 0 until size) {
        array[i] = scanner.nextInt()
    }

    // Find the minimum and maximum values in the array
    var min = array[0]
    var max = array[0]
    var minIndex = 0
    var maxIndex = 0
    for (i in 1 until size) {
        if (array[i] < min) {
            min = array[i]
            minIndex = i
        }
        if (array[i] > max) {
            max = array[i]
            maxIndex = i
        }
    }

    // Print the results
    println("Minimum Value: $min  at index $minIndex")
    println("Maximum Value: $max  at index $maxIndex")
}
```

