Function alphabeticalSort(array) {
  var length = array.length;
  for (var I = 0; I < length-1; i++) {
    for (var j = 0; j < length-i-1; j++) {
      if (array[j] > array[j+1]) {
        var temp = array[j];
        array[j] = array[j+1];
        array[j+1] = temp;
      }
    }
  }
  return array;
}
