```
function calculateArea() {
  var radius = document.getElementById("radius").value;
  var area;

  if (isNaN(radius) || radius == "") {
    document.getElementById("result").innerHTML = "Error: Please enter a positive number.";
  } else if (radius <= 0) {
    document.getElementById("result").innerHTML = "Error: Radius must be a positive number.";
  } else {
