#include <iostream>
#include <string>

using namespace std;

int main() {
    const int MAX_STUDENTS = 100; // maximum number of students that can be entered
    const int NUM_TESTS = 3; // number of tests each student takes

    int numStudents; // number of students in the class
    int scores[MAX_STUDENTS][NUM_TESTS]; // 2D array to hold all scores
    string names[MAX_STUDENTS]; // array to hold all student names
    float averages[MAX_STUDENTS]; // array to hold each student's average score

    // get the number of students in the class
    cout << "Enter the number of students in the class: ";
    cin >> numStudents;

    // get the scores and names for each student
    for (int I = 0; I < numStudents; i++) {
        cout << "Enter the name for student " << i+1 << ": ";
        cin >> names[i];

        cout << "Enter the scores for " << names[i] << ":\n";
        for (int j = 0; j < NUM_TESTS; j++) {
            cout << "Test " << j+1 << ": ";
            cin >> scores[i][j];
        }
        cout << endl;
    }

    // calculate and print each student's average score
    for (int I = 0; I < numStudents; i++) {
        float total = 0;
        for (int j = 0; j < NUM_TESTS; j++) {
            total += scores[i][j];
        }
        averages[i] = total / NUM_TESTS;
        cout << "Average score for " << names[i] << ": " << averages[i] << endl;
    }

    // calculate and print the average score for the entire class
    float classTotal = 0;
    for (int I = 0; I < numStudents; i++) {
        classTotal += averages[i];
    }
    float classAverage = classTotal / numStudents;
    cout << "\nAverage score for the entire class: " << classAverage << endl;

    // find and print the highest and lowest average scores and the corresponding student names
    float highestAverage = averages[0];
    float lowestAverage = averages[0];
    int highestIndex = 0;
    int lowestIndex = 0;
    for (int I = 1; I < numStudents; i++) {
        if (averages[i] > highestAverage) {
            highestAverage = averages[i];
            highestIndex = i;
        }
        if (averages[i] < lowestAverage) {
            lowestAverage = averages[i];
            lowestIndex = i;
        }
    }
    cout << "\nHighest average score: " << highestAverage << " (Student: " << names[highestIndex] << ")" << endl;
    cout << "Lowest average score: " << lowestAverage << " (Student: " << names[lowestIndex] << ")" << endl;

    return 0;
}

